+    for (size_t i = 0; i < len; i++) {
+        sum = (uint8_t)(sum + data[i]);
+    }
+    return sum;
+}
+
+int decompress_file(const unsigned char *compressed_data, size_t data_size,
+                    struct compression_context *ctx)
+{
+    /*
+     * Stage 1: Header Parsing
+     */
+    if (compressed_data == NULL || ctx == NULL) {
+        return -1;
+    }
+
+    if (data_size < CMP_MIN_SIZE) {
+        return -1;
+    }
+
+    /* Verify magic number */
+    if (compressed_data[0] != CMP_MAGIC_0 || compressed_data[1] != CMP_MAGIC_1) {
+        return -1;
+    }
+
+    /* Read compression type */
+    ctx->compression_type = compressed_data[2];
+
+    /* Read expected decompressed size */
+    size_t expected_size = 0;
+    memcpy(&expected_size, &compressed_data[3], sizeof(size_t));
+
+    if (expected_size == 0) {
+        return -1;
+    }
+
+    /* Allocate decompression buffer */
+    ctx->temp_buffer = (unsigned char *)malloc(expected_size);
+    if (ctx->temp_buffer == NULL) {
+        return -1;
+    }
+    ctx->buffer_size = expected_size;
+
+    /*
+     * Stage 2: Data Decompression
+     */
+    size_t payload_len = data_size - CMP_HEADER_LEN - CMP_CHECKSUM_LEN;
+    const unsigned char *payload = &compressed_data[CMP_HEADER_LEN];
+
+    if (ctx->compression_type == 0) {
+        /* Type 0: Raw — payload is the decompressed data */
+        if (payload_len != ctx->buffer_size) {
+            free(ctx->temp_buffer);
+            ctx->temp_buffer = NULL;
+            return -1;
+        }
+        memcpy(ctx->temp_buffer, payload, payload_len);
+
+    } else if (ctx->compression_type == 1) {
+        /* Type 1: RLE — payload is (count, value) pairs */
+        size_t out_pos = 0;
+        size_t i = 0;
+
+        while (i + 1 < payload_len) {
+            unsigned char count = payload[i];
+            unsigned char value = payload[i + 1];
+            i += 2;
+
+            for (unsigned int j = 0; j < count; j++) {
+                if (out_pos >= ctx->buffer_size) {
+                    free(ctx->temp_buffer);
+                    ctx->temp_buffer = NULL;
+                    return -1;
+                }
+                ctx->temp_buffer[out_pos++] = value;
+            }
+        }
+
+        /* Trailing odd byte is invalid */
+        if (i != payload_len) {
+            free(ctx->temp_buffer);
+            ctx->temp_buffer = NULL;
+            return -1;
+        }
+
+        /* Decompressed size must match expected */
+        if (out_pos != ctx->buffer_size) {
+            free(ctx->temp_buffer);
+            ctx->temp_buffer = NULL;
+            return -1;
+        }
+
+    } else {
+        /* Unsupported compression type */
+        free(ctx->temp_buffer);
+        ctx->temp_buffer = NULL;
+        return -1;
+    }
+
+    /*
+     * Stage 3: Integrity Verification
+     */
+    uint8_t stored_checksum = compressed_data[data_size - 1];
+    uint8_t computed_checksum = compute_checksum(ctx->temp_buffer, ctx->buffer_size);
+
+    if (stored_checksum != computed_checksum) {
+        free(ctx->temp_buffer);
+        ctx->temp_buffer = NULL;
+        return -1;
+    }
+
+    /* Success — caller is responsible for freeing ctx->temp_buffer */
+    return 0;
+}
